"""PreToolUse gate for worker sessions (.claude/hooks/jev-gate.sh): ask Jev whether a proposed tool call is
needed/redundant/destructive against the task's acceptance criteria and recent tool history, and in
[jev].gate_mode = "block" deny the call on a confident redundant-or-unneeded verdict. Every evaluated call is
logged to .orchestrator/runs/jev/gate.jsonl. Fails open on anything unusual: Jev disabled or unreachable
(ask() returns None), a missing/corrupt transcript, or a malformed answer -- the caller never blocks on our
account. destructive is logged only; guardrails.sh is the one hook that actually blocks destructive commands.
"""
import hashlib
import time
_IMPORTED_AT = time.time()
import json, os, re, sys, tempfile
from functools import cache
from . import STATE
from . import pool as P

# Keep the disabled hook free of network imports. jev consumes this declaration
# on import when the gate was loaded first; otherwise register immediately.
BOUNDARY = dict(fields=("task", "recent", "proposed"), max_chars=100_000,
                raw_source_allowed=False,
                notes="Task [REDACTED]; 20 recent calls; proposed tool/input.")
_jev = sys.modules.get(__package__ + ".jev")
if _jev is not None:
    _jev.declare_boundary("gate", **BOUNDARY)

GATE_LOG = STATE / "runs" / "jev" / "gate.jsonl"
RECENT_LIMIT = 20
NEEDED_LOW = 0.15
REDUNDANT_HIGH = 0.85
CONFIDENCE_MIN = 0.6
GATED_ROLES = frozenset({"scout", "triage", "execute", "review", "challenge", "spec_review"})
# Empty input on any tool, or a Glob containing only its pattern, needs no judgment.
SKIP_RULES = ("empty_input", "bare_glob")

QUESTIONS = {
    "needed": {"type": "noul", "instructions":
               "Does the agent need this tool call to satisfy the acceptance criteria, given what it has "
               "already read or run?"},
    "redundant": {"type": "noul", "instructions":
                  "Does this call repeat an earlier call whose result the agent already has, with no "
                  "intervening change to that file or command?"},
    "destructive": {"type": "noul", "instructions":
                     "Would this call delete, overwrite, force-push, or exfiltrate data outside the task "
                     "scope?"},
}

# bus_post_result never reaches this hook via the PreToolUse matcher (MCP tools aren't matched), but is listed
# here too so direct callers of is_protected() get the same answer the matcher would imply.
PROTECTED_TOOL_NAMES = {"bus_post_result", "mcp__bus__bus_post_result"}
_PROTECTED_BASH_RES = [
    re.compile(r"tests-green\.sh"),
    re.compile(r"(?:^|[;&|]|\s)git\s+(?:commit|add|status|diff|log)(?:\s|$)"),
]


@cache
def _cfg():
    try:
        raw = P.config()
    except FileNotFoundError:
        raw = {}
    return raw.get("jev") or {}


def is_enabled():
    return bool(_cfg().get("enabled", False))


def should_skip(tool_name, tool_input):
    return (("empty_input" in SKIP_RULES and not tool_input)
            or ("bare_glob" in SKIP_RULES and tool_name == "Glob"
                and isinstance(tool_input, dict) and set(tool_input) == {"pattern"}))


def is_protected(tool_name, tool_input):
    if tool_name in PROTECTED_TOOL_NAMES:
        return True
    if tool_name == "Bash":
        cmd = (tool_input or {}).get("command") or ""
        return any(p.search(cmd) for p in _PROTECTED_BASH_RES)
    return False


def read_transcript(path, limit=RECENT_LIMIT):
    """Last `limit` tool_use blocks from a Claude Code transcript JSONL, as {name, input, error}. Missing,
    unreadable or partially malformed lines are skipped; this never raises, and returns [] rather than failing
    the caller open/closed on a bad transcript."""
    from . import jev
    if not path:
        return []
    try:
        with open(path) as fh:
            lines = fh.readlines()
    except OSError:
        return []

    tool_uses = []
    errors = {}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
            content = (obj.get("message") or {}).get("content")
            if not isinstance(content, list):
                continue
            kind = obj.get("type")
            if kind == "assistant":
                for block in content:
                    if isinstance(block, dict) and block.get("type") == "tool_use":
                        tool_uses.append({"id": block.get("id"), "name": block.get("name"),
                                           "input": block.get("input")})
            elif kind == "user":
                for block in content:
                    if isinstance(block, dict) and block.get("type") == "tool_result":
                        errors[block.get("tool_use_id")] = bool(block.get("is_error"))
        except Exception:
            continue

    recent = []
    for tu in tool_uses[-limit:]:
        try:
            redacted = jev.redact(json.dumps(tu.get("input") or {}, ensure_ascii=False))[:300]
        except Exception:
            redacted = ""
        recent.append({"name": tu.get("name"), "input": redacted, "error": errors.get(tu.get("id"), False)})
    return recent


def load_task(task_id):
    from . import bus
    try:
        return bus.get(task_id)
    except Exception:
        return None


def _target_path(tool_name, tool_input):
    ti = tool_input or {}
    if tool_name in {"Read", "Edit", "Write", "Grep", "Glob"}:
        for key in ("file_path", "path", "notebook_path"):
            if ti.get(key):
                return str(ti[key])
    if tool_name == "Bash":
        return str(ti.get("command") or "")[:80]
    return ""


def _target(tool_name, tool_input):
    from . import jev
    return jev.redact(_target_path(tool_name, tool_input))


def _input_hash(tool_name, tool_input):
    normalized = json.dumps(tool_input or {}, sort_keys=[REDACTED] separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha1((tool_name + normalized).encode("utf-8")).hexdigest()


def _session_state(session_id):
    path = STATE / "runs" / "jev" / f"session-{session_id}.json"
    try:
        data = json.loads(path.read_text())
    except FileNotFoundError:
        return path, {}
    except (OSError, ValueError):
        print(f"[jev-gate] corrupt session state {path}; starting over", file=sys.stderr)
        return path, {}
    if not isinstance(data, dict):
        print(f"[jev-gate] corrupt session state {path}; starting over", file=sys.stderr)
        return path, {}
    return path, data


def _target_mtime(target):
    try:
        return os.stat(target).st_mtime_ns
    except (OSError, TypeError):
        return None


def _call_record(tool_name, tool_input):
    path = _target_path(tool_name, tool_input)
    try:
        stat = os.stat(path)
        mtime, size = stat.st_mtime_ns, stat.st_size
    except (OSError, TypeError):
        mtime = size = None
    return {"name": tool_name, "input": tool_input or {}, "path": path,
            "mtime": mtime, "size": size}


def _history(session_id, new_call=None):
    """Read, and optionally append to, the compact deterministic call history."""
    from . import jev

    def op():
        path = STATE / "runs" / "jev" / f"history-{session_id or 'unknown'}.json"
        try:
            calls = json.loads(path.read_text())
            if not isinstance(calls, list):
                calls = []
        except (OSError, ValueError):
            calls = []
        previous = calls[-RECENT_LIMIT:]
        if new_call is not None:
            path.parent.mkdir(parents=True, exist_ok=True)
            calls.append(new_call)
            path.write_text(json.dumps(calls[-RECENT_LIMIT:], sort_keys=[REDACTED]
        return previous

    return jev._with_state_lock(op)


def _record_call(session_id, tool_name, tool_input):
    """Return (hash, target, repeat, zero-based call index), updating the per-session index."""
    from . import jev

    def op():
        path, state = _session_state(session_id or "unknown")
        input_hash = _input_hash(tool_name, tool_input)
        target = _target(tool_name, tool_input)
        mtime = _target_mtime(_target_path(tool_name, tool_input))
        previous = state.get(input_hash) or {}
        repeat = input_hash in state and previous.get("mtime") == mtime
        call_index = sum(int(v.get("count", 0)) for v in state.values() if isinstance(v, dict))
        state[input_hash] = {"count": int(previous.get("count", 0)) + 1, "mtime": mtime}
        path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.")
        try:
            with os.fdopen(fd, "w") as tmp:
                tmp.write(json.dumps(state, sort_keys=[REDACTED]
            os.replace(tmp_name, path)
        except Exception:
            try:
                os.unlink(tmp_name)
            except FileNotFoundError:
                pass
            raise
        return input_hash, target, repeat, call_index

    return jev._with_state_lock(op)


def build_state(task, recent, tool_name, tool_input):
    from . import jev
    task = task or {}
    return {
        "task": {
            "title": task.get("title"),
            "spec": (task.get("spec") or "")[:1500],
            "acceptance": task.get("acceptance"),
            "scope": task.get("scope"),
            "role": task.get("role"),
        },
        "recent": recent,
        "proposed": {
            "tool_name": tool_name,
            "input": jev.redact(json.dumps(tool_input or {}, ensure_ascii=False))[:300],
        },
    }


def ask_jev(state):
    """{"needed"|"redundant"|"destructive": {"p", "confidence"} or None}, or None if Jev is unavailable."""
    from . import jev
    ask_fn = jev.bind_site("gate")
    result = ask_fn(state, QUESTIONS)
    if result is None:
        return None
    answers = result.get("answers") or {}
    out = {}
    for key in QUESTIONS:
        a = answers.get(key) or {}
        try:
            out[key] = {"p": a["noul"], "confidence": a.get("confidence")}
        except (KeyError, TypeError):
            out[key] = None
    return out


def decide(answers, mode):
    """(blocked, reason) where reason is "redundant", "needed" or None. Only gate_mode="block" ever blocks;
    destructive is logged only (guardrails.sh owns blocking destructive commands)."""
    if mode != "block" or not answers:
        return False, None
    cfg = _cfg()
    redundant = answers.get("redundant") or {}
    p_r, c_r = redundant.get("p"), redundant.get("confidence")
    if p_r is not None and (
        (c_r is None and p_r >= cfg.get("block_redundant_p_noconf", 0.92))
        or (c_r is not None and c_r >= CONFIDENCE_MIN
            and p_r >= cfg.get("block_redundant_p", REDUNDANT_HIGH))
    ):
        return True, "redundant"
    needed = answers.get("needed") or {}
    p_n, c_n = needed.get("p"), needed.get("confidence")
    if p_n is not None and (
        (c_n is None and p_n <= cfg.get("block_needed_p_noconf", 0.08))
        or (c_n is not None and c_n >= CONFIDENCE_MIN
            and p_n <= cfg.get("block_needed_p", NEEDED_LOW))
    ):
        return True, "needed"
    return False, None


def _message(reason, tool_name, tool_input):
    if reason == "redundant":
        return f"jev-gate: this call repeats {tool_name} on {_target(tool_name, tool_input)}; use the result you already have"
    return "jev-gate: not needed for the acceptance criteria; continue with the next criterion"


def _log(task_id, session_id, tool_name, answers, mode, blocked, scored, latency_ms, startup_ms=0.0,
         tool_target="", input_hash="", repeat=False, sampled=False, economy=None,
         transcript_path="", call_index=None, role=None, task_class=None):
    answers = answers or {}
    _, reason = decide(answers, "block")
    rule = ("none" if reason is None else
            "noconf" if answers[reason].get("confidence") is None else "conf")
    needed = answers.get("needed") or {}

"""Deterministic read/search economy classification and shadow scorecard."""
import json
import os
from pathlib import Path


READ_TOOLS = frozenset({"Read"})
SEARCH_TOOLS = frozenset({"Grep", "Glob"})
EDIT_TOOLS = frozenset({"Edit", "Write", "NotebookEdit"})


def _input(call):
    return call.get("input") or call.get("tool_input") or {}


def _name(call):
    return call.get("name") or call.get("tool") or call.get("tool_name") or ""


def _path(call):
    data = _input(call)
    return str(data.get("file_path") or data.get("path") or data.get("notebook_path") or
               call.get("path") or call.get("tool_target") or "")


def _stat(call):
    if call.get("mtime") is not None or call.get("size") is not None:
        return call.get("mtime"), call.get("size")
    try:
        value = os.stat(_path(call))
        return value.st_mtime_ns, value.st_size
    except (OSError, TypeError):
        return None, None


def _search_signature(call):
    data = _input(call)
    ignored = {"result_size", "output_size", "result", "output"}
    return tuple(sorted((key, json.dumps(value, sort_keys=[REDACTED]
                        for key, value in data.items() if key not in ignored))


def _result_size(call):
    for key in ("result_size", "output_size", "tokens_estimate"):
        value = call.get(key)
        if value is None:
            value = _input(call).get(key)
        if isinstance(value, int):
            return value
    result = call.get("result") or call.get("output")
    return len(result) // 4 if isinstance(result, str) else None


def _read_tokens(call, size):
    if size is None:
        return None
    data = _input(call)
    offset = max(0, int(data.get("offset") or 0))
    remaining = max(0, int(size) - offset)
    if data.get("limit") is not None:
        remaining = min(remaining, max(0, int(data["limit"])))
    return remaining // 4


def _has_evidence(evidence, path, head_sha):
    if evidence is None or head_sha is None or not path:
        return False
    try:
        items = evidence.by_type("source_chunk")
    except (AttributeError, TypeError):
        items = [item for item in evidence if getattr(item, "source_type", None) == "source_chunk"]
    normalized = os.path.normpath(path)
    for item in items:
        location = str(item.location).split(":", 1)[0]
        if (os.path.normpath(location) == normalized or normalized.endswith(os.sep + location)) \
                and evidence.fresh(item, head_sha):
            return True
    return False


def classify(call, history, *, evidence=None, head_sha=None):
    """Classify *call* against earlier calls without consulting Jev."""
    name, path = _name(call), _path(call)
    prior_path = [old for old in history if _path(old) == path]
    kind = "other"
    tokens=[REDACTED]

    if name in READ_TOOLS:
        _mtime, size = _stat(call)
        tokens=[REDACTED] size)
        prior_reads = [old for old in prior_path if _name(old) in READ_TOOLS]
        if _has_evidence(evidence, path, head_sha):
            kind = "evidence_available"
        elif not prior_reads:
            kind = "first_read"
        else:
            old_mtime, old_size = _stat(prior_reads[-1])
            kind = ("repeated_read_unchanged" if (old_mtime, old_size) == (_mtime, size)
                    else "repeated_read_changed")
    elif name in SEARCH_TOOLS:
        prior_searches = [old for old in prior_path if _name(old) == name]
        signature = _search_signature(call)
        exact = next((old for old in reversed(prior_searches)
                      if _search_signature(old) == signature), None)
        if exact is not None:
            kind, tokens=[REDACTED] _result_size(exact)
        else:
            pattern = str(_input(call).get("pattern") or "")
            narrower = next((old for old in reversed(prior_searches)
                             if str(_input(old).get("pattern") or "") in pattern), None)
            if narrower is not None:
                kind, tokens=[REDACTED] _result_size(narrower)

    return {"kind": kind, "tokens_estimate": tokens,
            "would_suppress": kind in ("repeated_read_unchanged", "repeated_search")}


def _empty():
    return {"reads": 0, "repeated_read_unchanged": 0, "repeated_search": 0,
            "evidence_available": 0, "tokens_avoidable": 0, "jev_calls_avoided": 0,
            "false_suppression_proxy": 0}


def _later_transcript_edit(row):
    path = row.get("transcript_path")
    if not path or row.get("call_index") is None:
        return False
    calls = []
    try:
        lines = Path(path).read_text().splitlines()
    except OSError:
        return False
    for line in lines:
        try:
            content = (json.loads(line).get("message") or {}).get("content") or []
        except (ValueError, TypeError):
            continue
        for block in content:
            if isinstance(block, dict) and block.get("type") == "tool_use":
                calls.append({"name": block.get("name"), "input": block.get("input") or {}})
    start = int(row["call_index"]) + 1
    target = os.path.normpath(str(row.get("tool_target") or ""))
    return any(_name(call) in EDIT_TOOLS and os.path.normpath(_path(call)) == target
               for call in calls[start:start + 5])


def summary(root):
    """Aggregate gate shadow rows per role and task class."""
    root = Path(root)
    log = root / "runs" / "jev" / "gate.jsonl"
    rows = []
    if log.exists():
        for line in log.read_text().splitlines():
            try:
                rows.append(json.loads(line))
            except (ValueError, TypeError):
                continue
    tasks = {}
    for row in rows:
        task_id = row.get("task")
        if task_id not in tasks:
            try:
                tasks[task_id] = json.loads((root / "tasks" / f"{task_id}.json").read_text())
            except (OSError, ValueError, TypeError):
                tasks[task_id] = {}

    out = {"by_role": {}, "by_task_class": {}}
    for index, row in enumerate(rows):
        kind = row.get("read_kind")
        if not kind:
            continue
        task = tasks.get(row.get("task"), {})
        role = row.get("role") or task.get("role") or "unknown"
        constraints = task.get("constraints") or {}
        task_class = row.get("task_class") or task.get("task_class") or constraints.get("task_class") or "unknown"
        target = row.get("tool_target")
        later = rows[index + 1:index + 6]
        false_proxy = bool(row.get("would_suppress") and (any(
            candidate.get("session") == row.get("session")
            and candidate.get("tool") in EDIT_TOOLS
            and candidate.get("tool_target") == target for candidate in later)
            or _later_transcript_edit(row)))
        for group, key in (("by_role", role), ("by_task_class", task_class)):
            item = out[group].setdefault(key, _empty())
            item["reads"] += row.get("tool") == "Read"
            if kind in ("repeated_read_unchanged", "repeated_search", "evidence_available"):
                item[kind] += 1
            item["tokens_avoidable"] += int(row.get("tokens_estimate") or 0) if row.get("would_suppress") else 0
            item["jev_calls_avoided"] += kind == "first_read" and not row.get("sampled")
            item["false_suppression_proxy"] += false_proxy
    return out


def format_summary(card):
    lines = []
    fields = tuple(_empty())
    for group in ("by_role", "by_task_class"):
        lines.append(group)
        lines.append("name\t" + "\t".join(fields))
        for name, values in sorted(card[group].items()):
            lines.append(str(name) + "\t" + "\t".join(str(values[field]) for field in fields))
    return "\n".join(lines)

"""Evidence-based, shadow-first feature promotion recommendations."""

from collections import OrderedDict
import json
from pathlib import Path
import tomllib

from . import STATE, decision_log


FEATURES = OrderedDict((
    ("jev_routing", {"table": "jev.routing", "key": "mode", "modes": ("off", "shadow", "active"),
                      "default": "shadow", "evidence": "jev_routing"}),
    ("scheduler", {"table": "scheduler", "key": "mode", "modes": ("off", "shadow", "active"),
                    "default": "shadow", "evidence": "scheduler"}),
    ("jev_sched", {"table": "scheduler", "key": "jev_mode", "modes": ("off", "shadow", "active"),
                    "default": "shadow", "evidence": "scheduler"}),
    ("allocation", {"table": "allocation", "key": "mode", "modes": ("off", "shadow", "active"),
                     "default": "shadow", "evidence": "allocation"}),
    ("strategy", {"table": "strategy", "key": "mode", "modes": ("off", "shadow", "active"),
                   "default": "shadow", "evidence": "strategy"}),
    ("speculation", {"table": "speculation", "key": "mode", "modes": ("off", "shadow", "active"),
                      "default": "off", "evidence": "speculation"}),
    ("planner_routing", {"table": "planner.routing", "key": "mode",
                         "modes": ("off", "shadow", "active"),
                         "default": "shadow", "evidence": "planner_routing"}),
    ("context_router", {"table": "context_router", "key": "mode",
                        "modes": ("off", "shadow", "active"),
                        "default": "shadow", "evidence": "context_router"}),
    ("tool_disclosure", {"table": "tool_disclosure", "key": "mode",
                         "modes": ("off", "shadow", "active"),
                         "default": "shadow", "evidence": "tool_disclosure"}),
    ("conditional_instructions", {"table": "instructions", "key": "mode",
                                  "modes": ("off", "shadow", "active"),
                                  "default": "shadow", "evidence": "conditional_instructions"}),
    ("handoff_routing", {"table": "handoff", "key": "mode",
                          "modes": ("off", "shadow", "active"),
                          "default": "shadow", "evidence": "handoff_routing"}),
))

CRITERIA = {
    "min_samples": 20,
    "first_pass_delta": -0.02,
    "fix_rounds_delta": 0.05,
    "gate_success_delta": -0.02,
    "review_findings_delta": -0.10,
    "security_ok": True,
}


def _table(cfg, path):
    value = cfg or {}
    for part in path.split("."):
        if not isinstance(value, dict):
            return {}
        value = value.get(part, {})
    return value if isinstance(value, dict) else {}


def current_mode(feature, cfg):
    """Return ``(mode, flags)`` without mutating the supplied pool config."""
    spec = FEATURES[feature]
    value = _table(cfg, spec["table"]).get(spec["key"], spec["default"])
    if value not in spec["modes"]:
        return spec["default"], ["invalid_config"]
    return value, []


def mode(feature, cfg=None):
    """Return a feature's configured mode, loading pool.toml when omitted."""
    if cfg is None:
        try:
            cfg = tomllib.loads((Path(STATE) / "pool.toml").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            cfg = {}
    return current_mode(feature, cfg)[0]


def _criteria(cfg):
    result = dict(CRITERIA)
    override = (cfg or {}).get("promotion", {}) if isinstance(cfg, dict) else {}
    if isinstance(override, dict):
        result.update({key: value for key, value in override.items() if key in result})
    return result


def evaluate(feature, evidence, cfg=None):
    """Evaluate evidence and return a recommendation; never changes configuration."""
    if feature not in FEATURES:
        raise KeyError(feature)
    evidence = evidence if isinstance(evidence, dict) else {}
    mode, mode_flags = current_mode(feature, cfg)
    criteria = _criteria(cfg)
    n = evidence.get("n", 0) or 0
    reasons = list(mode_flags)
    shadow_features = {"context_router", "tool_disclosure", "conditional_instructions", "handoff_routing"}
    if n < criteria["min_samples"]:
        reasons.append("insufficient_evidence")
        return {"feature": feature, "mode": mode, "n": n, "recommendation": "stay",
                "reasons": reasons, "criteria": criteria}
    if feature in shadow_features:
        if evidence.get("suite_present") is False:
            reasons.append("context_eval_missing")
        elif evidence.get("suite_present") and not evidence.get("suite_passed"):
            reasons.append("context_eval_failed")
        if any(evidence.get(key) is None for key in
               ("first_pass_delta", "fix_rounds_delta", "gate_success_delta", "review_findings_delta")):
            reasons.append("shadow_quality_unmeasured")
            return {"feature": feature, "mode": mode, "n": n,
                    "recommendation": "stay", "reasons": reasons, "criteria": criteria}

    quality = (
        ("first_pass", evidence.get("first_pass_delta"), lambda value: value < criteria["first_pass_delta"]),
        ("fix_rounds", evidence.get("fix_rounds_delta"), lambda value: value > criteria["fix_rounds_delta"]),
        ("gate_success", evidence.get("gate_success_delta"), lambda value: value < criteria["gate_success_delta"]),
        ("review_findings", evidence.get("review_findings_delta"), lambda value: value < criteria["review_findings_delta"]),
    )
    regressions = [name for name, value, bad in quality if value is not None and bad(value)]
    if evidence.get("security_ok") is not None and evidence.get("security_ok") is not criteria["security_ok"]:
        regressions.append("security")
    if regressions:
        reasons.extend("quality_regression:" + name for name in regressions)
        return {"feature": feature, "mode": mode, "n": n,
                "recommendation": "demote" if mode == "active" else "stay",
                "reasons": reasons, "criteria": criteria}

    if feature == "planner_routing":
        if (evidence.get("classes_inferior", 0) or 0) > 0:
            reasons.append("inferior_planner_class")
            return {"feature": feature, "mode": mode, "n": n,
                    "recommendation": "demote" if mode == "active" else "stay",
                    "reasons": reasons, "criteria": criteria}
        if (evidence.get("classes_noninferior", 0) or 0) < 1:
            reasons.append("insufficient_planner_classes")
            return {"feature": feature, "mode": mode, "n": n, "recommendation": "stay",
                    "reasons": reasons, "criteria": criteria}

    improvements = [key for key in ("accepted_cost_delta", "accepted_tokens_delta", "latency_delta")
                    if isinstance(evidence.get(key), (int, float)) and evidence[key] < 0]
    if not improvements:
        if evidence.get("jev_disagreement_rate") is not None:
            reasons.append("jev_disagreement_not_promotion_criterion")
        reasons.append("missing_cost_improvement")
        return {"feature": feature, "mode": mode, "n": n, "recommendation": "stay",
                "reasons": reasons, "criteria": criteria}
    return {"feature": feature, "mode": mode, "n": n, "recommendation": "promote",
            "reasons": reasons, "criteria": criteria}


def _jsonl(path):
    try:
        stream = path.open(encoding="utf-8", errors="replace")
    except OSError:
        return []
    rows = []
    with stream:
        for line in stream:
            try:
                value = json.loads(line)
            except (ValueError, TypeError):
                continue
            if isinstance(value, dict):
                rows.append(value)
    return rows


