        subprocess.run(["git", "add", "."], cwd=wt, check=True)
        subprocess.run(["git", "-c", "user.name=Context Eval", "-c", "user.email=eval@invalid",
                        "commit", "-qm", "fixture"], cwd=wt, check=True)
    scope = {
        "localized_fix": ["app.py"], "cross_cutting": list(files),
        "security": ["auth/security.py"], "test_failure": ["app.py", "tests/test_app.py"],
        "documentation": ["docs/missing.py"], "review": ["app.py"],
        "repeated_fix_round": ["app.py"],
    }[category]
    spec = "Fix the target with supporting context."
    constraints = {"task_class": category}
    if category == "test_failure":
        spec += "\nFailures:\ntests/test_app.py::test_target FAIL named failure"
        constraints["fix_round_for"] = "T-EVAL-BASE"
    if category == "repeated_fix_round":
        constraints["fix_round_for"] = "T-EVAL-BASE"
        spec += "\nFailures:\ntests/test_app.py::test_target FAIL repeated"
    inputs = [{"summary": "unrelated historical material " * 10}
              for _ in range(18 if category == "localized_fix" else 5 if category == "cross_cutting" else 0)]
    task = {"id": "T-EVAL-" + category.upper(), "role": "review" if category in ("review", "security") else "execute",
            "title": category.replace("_", " "), "spec": spec,
            "acceptance": ["tests/test_app.py::test_target passes"], "scope": scope,
            "constraints": constraints, "worktree": str(wt), "parent": None, "inputs": inputs}
    if category in ("review", "security"):
        target = wt / ("auth/security.py" if category == "security" else "app.py")
        target.write_text(target.read_text() + "\n# pending review change\n")
    return wt, task


def _cfg(mode):
    return {"context_router": {"mode": mode}, "tool_disclosure": {"mode": mode},
            "instructions": {"mode": mode}, "handoff": {"mode": mode},
            "review": {"security_paths": ["auth/*"]}, "limits": {"review_diff_chars": 12000}}


def _selection(root, subject):
    path = Path(root) / "runs" / "sched" / "decisions.jsonl"
    rows = []
    for line in path.read_text(encoding="utf-8").splitlines() if path.exists() else ():
        try:
            row = json.loads(line)
        except (ValueError, TypeError):
            continue
        if row.get("kind") == "context_selection" and row.get("subject") == subject:
            rows.append(row)
    return rows[-1] if rows else {}


def run(category, root):
    if category not in CATEGORIES:
        raise ValueError(category)
    with isolated_state(root) as state:
        wt, task = _fixture(category, root)
        builder = spawn.review_packet if task["role"] == "review" else spawn.packet
        if task["role"] == "review":
            original_diff = spawn.scoped_diff
            spawn.scoped_diff = lambda _task: subprocess.run(
                ["git", "diff", "--", *task["scope"]], cwd=wt,
                capture_output=True, text=True, check=True).stdout
            try:
                off_text = builder(task, task, cfg=_cfg("off"))
                off_meta = {"presented_tokens": len(off_text) // 4}
                shadow_text = builder(task, task, cfg=_cfg("shadow"))
            finally:
                spawn.scoped_diff = original_diff
        else:
            off_text = builder(task, wt, cfg=_cfg("off"))
            off_meta = spawn.packet_run_meta(off_text)
            shadow_text = builder(task, wt, cfg=_cfg("shadow"))
        meta = spawn.packet_run_meta(shadow_text)
        decision = _selection(state, task["id"])
        deterministic = decision.get("deterministic") or {}
        candidates = int(deterministic.get("candidate_tokens") or meta.get("candidate_tokens") or 0)
        routed = int(deterministic.get("routed_tokens") or meta.get("routed_tokens") or candidates)
        reduction = round(1 - routed / candidates, 3) if candidates else 0.0
        tagged = decision.get("candidates") or []
        full = [value.rsplit(":", 1)[0] for value in tagged if value.endswith(":FULL")]
        full_reasons = decision.get("hard_constraints") or []
        must_keep, kept = [], True
        if category == "localized_fix":
            must_keep = ["app.py"]
        elif category == "security":
            must_keep = ["auth/security.py", "security instructions"]
            kept = "security_path" in full_reasons and "## security" in shadow_text
        elif category == "test_failure":
            must_keep = ["failing output", "tests/test_app.py::test_target"]
            kept = full_reasons.count("failing_output") >= 1 and "tests/test_app.py::test_target" in off_text
        elif category == "documentation":
            must_keep = ["no source_chunk FULL"]
            kept = not any("source_chunk" in value for value in full)
        elif category == "review":
            must_keep = ["diff", "acceptance", "interfaces", "no implementation transcript"]
            kept = all("## " + name in shadow_text for name in ("diff", "acceptance", "scope")) and "transcript" not in shadow_text.lower()
        elif category == "repeated_fix_round":
            must_keep = ["prior evidence overlap >= 0.8"]
            first = set(meta.get("evidence_ids") or [])
            again = builder(task, wt, cfg=_cfg("shadow"))
            second = set(spawn.packet_run_meta(again).get("evidence_ids") or [])
            kept = len(first & second) / max(1, len(first)) >= .8
        else:
            kept = bool(full)
        if category == "localized_fix":
            kept = "in_scope_file" in full_reasons
        low, high = EXPECTATIONS[category]
        instruction_modular = meta.get("instruction_tokens_modular")
        return {"category": category, "candidate_tokens": candidates,
                "presented_tokens": off_meta["presented_tokens"], "routed_tokens": routed,
                "reduction": reduction, "hidden": int(deterministic.get("HIDE") or meta.get("routed_hidden") or 0),
                "instruction_delta": (instruction_modular - off_meta["presented_tokens"]
                                      if isinstance(instruction_modular, int) else 0),
                "tool_delta": int(meta.get("tool_tokens_minimal") or 0) - int(meta.get("tool_tokens_disclosed") or 0),
                "expectation": {"min_reduction": low, "max_reduction": high},
                "within_expectation": low <= reduction <= high, "must_keep": must_keep, "kept": kept}


def run_all(root=None):
    base = Path(root) if root else Path(tempfile.mkdtemp(prefix="orchestrator-context-eval-"))
    return [run(category, base / category) for category in CATEGORIES]


def result_document(results):
    try:
        head = subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    except OSError:
        head = ""
    return {"ran_at": datetime.now(timezone.utc).isoformat(), "git_head": head or "(unavailable)",
            "results": results, "suite_passed": all(x["within_expectation"] and x["kept"] for x in results)}


def format_report(results):
    lines = ["category\tcandidate\tpresented\trouted\treduction\thidden\twithin\tkept"]
    lines += [f"{r['category']}\t{r['candidate_tokens']}\t{r['presented_tokens']}\t{r['routed_tokens']}\t{r['reduction']}\t{r['hidden']}\t{r['within_expectation']}\t{r['kept']}" for r in results]
    return "\n".join(lines)

"""Context-economy reporting from run-log packet telemetry."""
import json
from collections import defaultdict
from pathlib import Path

from . import STATE, attribution


def _entries(root):
    for path in sorted((Path(root) / "runs").glob("*.jsonl")):
        for line in path.read_text().splitlines():
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue


def _avg(values):
    return round(sum(values) / len(values), 2) if values else None


def _shadow(rows):
    contexts = [row["context"] for row in rows if isinstance(row.get("context"), dict)]
    measured = [context for context in contexts if context.get("routed_tokens") is not None]
    candidates = [len(context.get("evidence_ids") or []) for context in measured]
    return {
        "shadow_routed_tokens": _avg([context["routed_tokens"] for context in measured]),
        "shadow_reduction": _avg([context["routed_reduction_ratio"] for context in measured
                                  if context.get("routed_reduction_ratio") is not None]),
        "shadow_hidden": _avg([context["routed_hidden"] for context in measured
                               if context.get("routed_hidden") is not None]),
        "shadow_ambiguous_rate": _avg([
            context.get("routed_ambiguous", 0) / count for context, count in zip(measured, candidates) if count]),
        "shadow_unmeasured": len(rows) - len(measured),
    }


def build(root=STATE):
    entries = list(_entries(root))
    tasks = {}
    for path in sorted((Path(root) / "tasks").glob("*.json")):
        try:
            task = json.loads(path.read_text())
            tasks[task.get("id", path.stem)] = task
        except (OSError, ValueError, TypeError):
            continue
    roles = {}
    for role in sorted({row.get("role") or "?" for row in entries}):
        rows = [row for row in entries if (row.get("role") or "?") == role]
        measured = [row for row in rows if isinstance(row.get("context"), dict)]
        presented = [row["context"].get("presented_tokens") for row in measured
                     if row["context"].get("presented_tokens") is not None]
        candidate_rows = [row for row in measured if row["context"].get("candidate_known")
                          and row["context"].get("candidate_tokens") is not None]
        candidate = [row["context"]["candidate_tokens"] for row in candidate_rows]
        candidate_presented = [row["context"].get("presented_tokens", 0) for row in candidate_rows]
        instructions = [row["context"].get("instruction_tokens") for row in measured
                        if row["context"].get("instruction_tokens") is not None]
        modular_rows = [row for row in measured
                        if row["context"].get("instruction_tokens_modular") is not None]
        modular = [row["context"]["instruction_tokens_modular"] for row in modular_rows]
        modular_legacy = [row["context"].get("instruction_tokens") for row in modular_rows]
        disclosed = [row["context"].get("tool_tokens_disclosed") for row in measured
                     if row["context"].get("tool_tokens_disclosed") is not None]
        minimal = [row["context"].get("tool_tokens_minimal") for row in measured
                   if row["context"].get("tool_tokens_minimal") is not None]
        sections = defaultdict(list)
        for row in measured:
            for name, meta in (row["context"].get("sections") or {}).items():
                sections[name].append(meta.get("est_tokens", 0))
        roles[role] = {"runs": len(rows), "measured": len(measured),
                       "unmeasured": len(rows) - len(measured), "avg_presented": _avg(presented),
                       "avg_candidate": _avg(candidate),
                       "reduction_ratio": round(1 - sum(candidate_presented) / sum(candidate), 3)
                       if candidate and sum(candidate) else None,
                       "avg_instruction_tokens": _avg(instructions),
                       "instruction_tokens": _avg(instructions),
                       "instruction_tokens_modular": _avg(modular),
                       "instruction_reduction": round(sum(modular) / sum(modular_legacy), 3)
                       if modular_legacy and sum(modular_legacy) else None,
                       "instruction_unmeasured": len(rows) - len(modular_rows),
                       "tool_tokens_disclosed": _avg(disclosed), "tool_tokens_minimal": _avg(minimal),
                       "tool_reduction": round(sum(minimal) / sum(disclosed), 3) if disclosed and sum(disclosed) else None,
                       "top_sections": sorted(((name, _avg(values)) for name, values in sections.items()),
                                              key=[REDACTED] item: (-item[1], item[0]))[:5], **_shadow(rows)}
    goals = {}
    for goal in sorted({row.get("goal_id") for row in entries if row.get("goal_id")}):
        rows = [row for row in entries if row.get("goal_id") == goal]
        measured = [row for row in rows if isinstance(row.get("context"), dict)]
        total = unique = 0
        by_section = {}
        occurrences = defaultdict(list)
        for row in measured:
            for name, meta in (row["context"].get("sections") or {}).items():
                token_count=[REDACTED] 0)
                total += token_count
                occurrences[name].append((meta.get("sha256"), token_count, row.get("role")))
        for name, values in occurrences.items():
            unique_tokens=[REDACTED] for digest2, tokens, _ in values if digest2 == digest)
                                for digest in {digest for digest, _, _ in values})
            by_section[name] = round(sum(tokens for _, tokens, _ in values) / unique_tokens, 3) if unique_tokens else 0.0
            unique += unique_tokens
        repeated = sorted(name for name, values in occurrences.items()
                          if any(len({role for digest2, _, role in values if digest2 == digest}) >= 2
                                 for digest in {digest for digest, _, _ in values}))
        goals[goal] = {"runs": len(rows), "measured": len(measured),
                       "amplification": round(total / unique, 3) if unique else None,
                       "amplification_by_section": by_section, "repeated_sections": repeated,
                       "lineage_roots": sorted({row.get("lineage_root") for row in rows if row.get("lineage_root")}),
                       **_shadow(rows)}
    by_role_class = {}
    for key in sorted({(row.get("role") or "unknown",
                        attribution.task_class(tasks[row.get("task")]) if row.get("task") in tasks else "unknown")
                       for row in entries}):
        selected = [row for row in entries if (row.get("role") or "unknown") == key[0] and
                    (attribution.task_class(tasks[row.get("task")]) if row.get("task") in tasks else "unknown") == key[1]]
        contexts = [row["context"] for row in selected if isinstance(row.get("context"), dict)]
        disclosed = [c["tool_tokens_disclosed"] for c in contexts if c.get("tool_tokens_disclosed") is not None]
        minimal = [c["tool_tokens_minimal"] for c in contexts if c.get("tool_tokens_minimal") is not None]
        by_role_class[key] = {"runs": len(selected), "measured": len(contexts),
                              "tool_tokens_disclosed": _avg(disclosed), "tool_tokens_minimal": _avg(minimal),
                              "tool_reduction": round(sum(minimal) / sum(disclosed), 3) if disclosed and sum(disclosed) else None,
                              **_shadow(selected)}
    return {"roles": roles, "goals": goals, "by_role_task_class": by_role_class}


def format_report(card):
    lines = ["Per role", "role\truns\tmeasured\tunmeasured\tavg presented\tavg candidate\treduction\tavg instructions\tmodular instructions\tinstruction reduction\ttool disclosed\ttool minimal\ttool reduction\tshadow routed\tshadow reduction\tshadow hidden\tshadow ambiguous\tshadow unmeasured\ttop sections"]
    for role, row in card["roles"].items():
        lines.append("\t".join(map(str, (role, row["runs"], row["measured"], row["unmeasured"],
                                          row["avg_presented"], row["avg_candidate"], row["reduction_ratio"],
                                          row["avg_instruction_tokens"], row["instruction_tokens_modular"],
                                          row["instruction_reduction"], row["tool_tokens_disclosed"],
                                          row["tool_tokens_minimal"], row["tool_reduction"],
                                          row["shadow_routed_tokens"],
                                          row["shadow_reduction"], row["shadow_hidden"],
                                          row["shadow_ambiguous_rate"], row["shadow_unmeasured"],
                                          row["top_sections"]))))
    lines += ["", "Per goal", "goal\truns\tmeasured\tamplification\tshadow routed\tshadow reduction\tshadow hidden\tshadow ambiguous\tshadow unmeasured\tby section\trepeated\tlineage roots"]
    for goal, row in card["goals"].items():
        lines.append("\t".join(map(str, (goal, row["runs"], row["measured"], row["amplification"],
                                          row["shadow_routed_tokens"], row["shadow_reduction"],
                                          row["shadow_hidden"], row["shadow_ambiguous_rate"],
                                          row["shadow_unmeasured"],
                                          row["amplification_by_section"], row["repeated_sections"], row["lineage_roots"]))))
    return "\n".join(lines)

"""Canonical, content-addressed evidence for deterministic context selection.

Evidence content is raw in memory.  :class:`EvidencePool` always applies
``jev.redact`` before persistence so secrets are never written to its JSONL file.
"""
from dataclasses import asdict, dataclass, replace
import hashlib
import json
import re
import time
from pathlib import Path

from . import STATE, jev


SOURCE_TYPES = (
    "source_chunk", "test_result", "scout_finding", "memory_entry",
    "graph_finding", "previous_result", "review_finding",
    "architecture_note", "decision", "external_doc",
)
PROVENANCE = ("repo", "bus", "memory", "scout", "external")


@dataclass(frozen=True)
class Evidence:
    id: str
    source_type: str
    location: str
    commit: str
    content_hash: str
    content: str
    summary_short: str
    summary_long: str
    relevance: dict
    provenance: str
    observed_at: float
    trust: str


def _scope(task):
    return (task or {}).get("scope") or (task or {}).get("write_scope") or []


def _location_path(location):
    return str(location).split(":", 1)[0]


def relevance_for(ev, task):
    """Compute relevance for *task*; stored relevance is only a per-task cache."""
    title = str((task or {}).get("title") or (task or {}).get("objective") or "")
    content = ev.content if isinstance(ev, Evidence) else str(ev)
    location = ev.location if isinstance(ev, Evidence) else ""
    lower = content.lower()
    title_terms = {word.lower() for word in re.findall(r"[A-Za-z0-9_]+", title) if len(word) >= 4}
    scope = [str(path) for path in _scope(task)]
    stems = {Path(path).stem.lower() for path in scope if Path(path).stem}
    return {
        "scope_match": _location_path(location) in scope,
        "title_terms": sum(term in lower for term in title_terms),
        "path_terms": sum(stem in lower for stem in stems),
        "recent_task": (task or {}).get("id") or None,
    }


def _collapse(value):
    return " ".join(str(value).split())


def make(source_type, location, content, *, commit="", provenance, task=None,
         scope=(), summary_long=None, observed_at=None):
    if source_type not in SOURCE_TYPES:
        raise ValueError(f"invalid source_type: {source_type}")
    if provenance not in PROVENANCE:
        raise ValueError(f"invalid provenance: {provenance}")
    content = str(content)
    content_hash = hashlib.sha256(content.encode()).hexdigest()
    evidence_id = hashlib.sha256(
        f"{source_type}|{location}|{content_hash}".encode()
    ).hexdigest()[:12]
    meaningful = next((line.strip() for line in content.splitlines() if line.strip()), "")
    short = _collapse(meaningful)[:160]
    long = _collapse(content if summary_long is None else summary_long)[:600]
    relevance_task = task
    if relevance_task is None and scope:
        relevance_task = {"scope": list(scope)}
    provisional = Evidence(
        evidence_id, source_type, str(location), str(commit), content_hash,
        content, short, long, {}, provenance,
        time.time() if observed_at is None else float(observed_at),
        "trusted" if provenance in ("repo", "memory") else "untrusted",
    )
    return replace(provisional, relevance=relevance_for(provisional, relevance_task))


def fresh(ev, head_sha):
    return ev.source_type not in ("source_chunk", "test_result") or ev.commit == head_sha


def cache_key(ev, task_class, role, level):
    value = f"{ev.content_hash}|{task_class}|{role}|{level}"
    return hashlib.sha256(value.encode()).hexdigest()[:16]


class EvidencePool:
    """Goal-bound JSONL store; content is redacted with ``jev.redact`` on disk."""

    def __init__(self, goal):
        self.path = STATE / "evidence" / f"{goal}.jsonl"
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._items = {}
        if self.path.exists():
            for line in self.path.read_text().splitlines():
                if line.strip():
                    row = json.loads(line)
                    self._items[row["id"]] = Evidence(**row)

    def add(self, ev):
        if ev.id in self._items:
            return self._items[ev.id]
        persisted = replace(ev, content=jev.redact(ev.content),
                            summary_short=jev.redact(ev.summary_short),
                            summary_long=jev.redact(ev.summary_long))
        self._items[ev.id] = persisted
        with self.path.open("a") as handle:
            handle.write(json.dumps(asdict(persisted), sort_keys=[REDACTED] + "\n")
        return persisted

    def get(self, evidence_id):
        return self._items.get(evidence_id)

    def by_type(self, source_type):
        return [ev for ev in self._items.values() if ev.source_type == source_type]

    @staticmethod
    def fresh(ev, head_sha):
        return fresh(ev, head_sha)

    def stale_ids(self, head_sha):
        return [ev.id for ev in self._items.values() if not fresh(ev, head_sha)]

